class Solution {
public:
    int maximumAmount(vector<vector<int>>& coins) {
        int m = coins.size(), n = coins[0].size();
        const int NEG = INT_MIN / 2;
        vector<array<int,3>> dp(n), ndp(n);
        for (int j = 0; j < n; j++) dp[j] = {NEG, NEG, NEG};
        dp[0][0] = coins[0][0];
        if (coins[0][0] < 0) dp[0][1] = 0;
        for (int j = 1; j < n; j++) {
            int c = coins[0][j];
            for (int k = 0; k < 3; k++) {
                int best = dp[j-1][k];
                if (best > NEG) best += c; else best = NEG;
                dp[j][k] = best;
                if (c < 0 && k > 0 && dp[j-1][k-1] > NEG)
                    dp[j][k] = max(dp[j][k], dp[j-1][k-1]);
            }
        }
        for (int i = 1; i < m; i++) {
            for (int j = 0; j < n; j++) ndp[j] = {NEG, NEG, NEG};
            int c = coins[i][0];
            for (int k = 0; k < 3; k++) {
                int best = dp[0][k];
                if (best > NEG) best += c; else best = NEG;
                ndp[0][k] = best;
                if (c < 0 && k > 0 && dp[0][k-1] > NEG)
                    ndp[0][k] = max(ndp[0][k], dp[0][k-1]);
            }
            for (int j = 1; j < n; j++) {
                int c2 = coins[i][j];
                for (int k = 0; k < 3; k++) {
                    int best = max(dp[j][k], ndp[j-1][k]);
                    if (best > NEG) best += c2; else best = NEG;
                    ndp[j][k] = best;
                    if (c2 < 0 && k > 0) {
                        int nb = max(dp[j][k-1], ndp[j-1][k-1]);
                        if (nb > NEG) ndp[j][k] = max(ndp[j][k], nb);
                    }
                }
            }
            swap(dp, ndp);
        }
        return max({dp[n-1][0], dp[n-1][1], dp[n-1][2]});
    }
};
